-- P3-02: workspace, board, note and card schema (AD-4, AD-5).
--
-- UUIDs are UUIDv7 values generated by the application; the database stores
-- plain `uuid` (no extension). Timestamps are `timestamptz`; card geometry uses
-- `double precision`; `z` is the contract's fractional-index string (1-64
-- alphanumerics). Text limits come from ADR-0004.
--
-- Applied migrations are immutable (the runner records a SHA-256 checksum and
-- fails when an applied file changes): later changes arrive as new numbered
-- files. Row-level security for these tables lives in 0003_rls_policies.sql.
--
-- Invariants enforced here for every role, including the migration owner:
-- * exactly one `owner` membership per workspace, created by the workspace
--   trigger; nobody can insert a second owner row or promote a member to owner;
-- * `notes.workspace_id` and `boards.workspace_id` are immutable in v1. Moving
--   either would leave cards whose board and note live in different
--   workspaces, so a move is rejected until a transactional move exists;
-- * a card always places a note of the board's own workspace;
-- * the owner of a workspace cannot be deleted while the workspace exists.

CREATE TYPE app.workspace_role AS ENUM ('owner', 'editor', 'reader');

CREATE TYPE app.board_visibility AS ENUM ('private', 'workspace', 'link');

-- One row per account. `account_id` is the Kratos identity id; profiles holds
-- only the local display data, never credentials or e-mail.
CREATE TABLE app.profiles (
  account_id uuid PRIMARY KEY,
  display_name text NOT NULL,
  locale text NOT NULL DEFAULT 'de',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT profiles_display_name_length CHECK (char_length(display_name) BETWEEN 1 AND 80),
  CONSTRAINT profiles_locale_values CHECK (locale IN ('de', 'en'))
);

CREATE TABLE app.workspaces (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  owner_account_id uuid NOT NULL REFERENCES app.profiles (account_id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT workspaces_name_length CHECK (char_length(name) BETWEEN 1 AND 120)
);

-- The permission source for row-level security. A workspace always has exactly
-- one `owner` row for its owner; the triggers below create it, keep it in place
-- and reject any other `owner` row, so a foreign, ownerless or double-owned
-- workspace is impossible.
CREATE TABLE app.workspace_members (
  workspace_id uuid NOT NULL REFERENCES app.workspaces (id) ON DELETE CASCADE,
  account_id uuid NOT NULL REFERENCES app.profiles (account_id) ON DELETE CASCADE,
  role app.workspace_role NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, account_id)
);

CREATE TABLE app.boards (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES app.workspaces (id) ON DELETE CASCADE,
  owner_account_id uuid NOT NULL REFERENCES app.profiles (account_id) ON DELETE RESTRICT,
  title text NOT NULL,
  visibility app.board_visibility NOT NULL DEFAULT 'private',
  archived boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT boards_title_length CHECK (char_length(title) BETWEEN 1 AND 200)
);

-- A note exists once (AD-4); a card is only its placement on a board. Deleting
-- a workspace therefore deletes its notes, while a note that still has cards
-- cannot be deleted by accident (`cards.note_id` is ON DELETE RESTRICT).
CREATE TABLE app.notes (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES app.workspaces (id) ON DELETE CASCADE,
  title text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT notes_title_length CHECK (char_length(title) <= 300)
);

-- `zone_id` is a plain uuid for now: zones arrive in a later backend task, so
-- there is no foreign key to a table that does not exist yet.
CREATE TABLE app.cards (
  id uuid PRIMARY KEY,
  board_id uuid NOT NULL REFERENCES app.boards (id) ON DELETE CASCADE,
  note_id uuid NOT NULL REFERENCES app.notes (id) ON DELETE RESTRICT,
  zone_id uuid,
  x double precision NOT NULL,
  y double precision NOT NULL,
  width double precision NOT NULL,
  height double precision NOT NULL,
  z text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT cards_minimum_size CHECK (width >= 176 AND height >= 80),
  CONSTRAINT cards_z_format CHECK (z ~ '^[A-Za-z0-9]{1,64}$')
);

-- Indexes for the list queries: workspace -> boards -> cards, note lookups and
-- the membership checks every row-level-security policy performs.
CREATE INDEX workspaces_owner_account_id_idx ON app.workspaces (owner_account_id);
CREATE INDEX workspace_members_account_id_idx ON app.workspace_members (account_id);
CREATE INDEX boards_workspace_id_updated_at_idx ON app.boards (workspace_id, updated_at DESC);
CREATE INDEX boards_owner_account_id_idx ON app.boards (owner_account_id);
CREATE INDEX notes_workspace_id_updated_at_idx ON app.notes (workspace_id, updated_at DESC);
CREATE INDEX cards_board_id_z_idx ON app.cards (board_id, z);
CREATE INDEX cards_note_id_idx ON app.cards (note_id);
CREATE INDEX cards_zone_id_idx ON app.cards (zone_id);
-- Exactly one owner membership per workspace. The workspace trigger creates it;
-- this index makes a second owner row impossible even for the migration owner.
CREATE UNIQUE INDEX workspace_members_one_owner_idx
  ON app.workspace_members (workspace_id)
  WHERE role = 'owner';

-- Creating a workspace atomically creates the owner membership row.
CREATE FUNCTION app.workspace_add_owner_membership() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO app.workspace_members (workspace_id, account_id, role)
  VALUES (NEW.id, NEW.owner_account_id, 'owner');
  RETURN NULL;
END;
$$;

CREATE TRIGGER workspaces_add_owner_membership
AFTER INSERT ON app.workspaces
FOR EACH ROW EXECUTE FUNCTION app.workspace_add_owner_membership();

-- Only the workspace's owner_account_id may hold the owner role, and the owner
-- row is created by the workspace trigger only. A member can never be promoted
-- through the membership table, so exactly one live owner row exists.
CREATE FUNCTION app.validate_workspace_owner_role() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.role = 'owner' THEN
    IF NEW.account_id <> (
      SELECT workspace.owner_account_id
      FROM app.workspaces AS workspace
      WHERE workspace.id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'only the workspace owner may hold the owner role';
    END IF;
    -- 1 = a direct statement; the workspace trigger inserts this row one level
    -- deeper, which is the only allowed path.
    IF pg_trigger_depth() < 2 THEN
      RAISE EXCEPTION 'the owner membership row is created with the workspace and cannot be inserted directly';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER workspace_members_validate_owner
BEFORE INSERT OR UPDATE ON app.workspace_members
FOR EACH ROW EXECUTE FUNCTION app.validate_workspace_owner_role();

-- The owner membership row and the workspace owner can never be removed or
-- changed through the membership table; transferring a workspace is a later
-- feature with its own migration.
CREATE FUNCTION app.protect_owner_membership() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.role = 'owner' THEN
    -- A workspace deletion cascades into its memberships; only a membership
    -- change while the workspace still exists is an error.
    IF EXISTS (SELECT 1 FROM app.workspaces AS workspace WHERE workspace.id = OLD.workspace_id) THEN
      RAISE EXCEPTION 'the owner membership of a workspace cannot be changed or removed';
    END IF;
  END IF;
  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

CREATE TRIGGER workspace_members_protect_owner
BEFORE UPDATE OR DELETE ON app.workspace_members
FOR EACH ROW EXECUTE FUNCTION app.protect_owner_membership();

CREATE FUNCTION app.protect_workspace_owner() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.owner_account_id <> OLD.owner_account_id THEN
    RAISE EXCEPTION 'workspace ownership transfer is not supported yet';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER workspaces_protect_owner
BEFORE UPDATE OF owner_account_id ON app.workspaces
FOR EACH ROW EXECUTE FUNCTION app.protect_workspace_owner();

-- v1: a note and a board belong to the workspace they were created in. A move
-- would leave cards whose board and note workspaces differ, so it is rejected
-- here for every role; a later task may add a transactional move.
CREATE FUNCTION app.protect_note_workspace() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.workspace_id <> OLD.workspace_id THEN
    RAISE EXCEPTION 'moving a note to another workspace is not supported yet';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER notes_protect_workspace
BEFORE UPDATE OF workspace_id ON app.notes
FOR EACH ROW EXECUTE FUNCTION app.protect_note_workspace();

CREATE FUNCTION app.protect_board_workspace() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.workspace_id <> OLD.workspace_id THEN
    RAISE EXCEPTION 'moving a board to another workspace is not supported yet';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER boards_protect_workspace
BEFORE UPDATE OF workspace_id ON app.boards
FOR EACH ROW EXECUTE FUNCTION app.protect_board_workspace();

-- Deleting the account that owns a workspace fails with a clear message before
-- the membership cascade can hit the owner-membership guard (the foreign keys
-- would RESTRICT as well). Deleting a non-owner account cascades its
-- memberships.
CREATE FUNCTION app.protect_profile_owner_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM app.workspaces AS workspace
    WHERE workspace.owner_account_id = OLD.account_id
  ) THEN
    RAISE EXCEPTION 'the owner of a workspace cannot be deleted while the workspace exists';
  END IF;
  RETURN OLD;
END;
$$;

CREATE TRIGGER profiles_protect_owner_delete
BEFORE DELETE ON app.profiles
FOR EACH ROW EXECUTE FUNCTION app.protect_profile_owner_delete();

-- A card may only place a note that lives in the board's own workspace. Row
-- level security enforces this for app_user below; the trigger keeps the
-- invariant for every role, including the migration owner. Together with the
-- immutable note/board workspaces above, a card can never straddle two
-- workspaces.
CREATE FUNCTION app.protect_card_note_workspace() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM app.notes AS note
    JOIN app.boards AS board ON board.workspace_id = note.workspace_id
    WHERE note.id = NEW.note_id
      AND board.id = NEW.board_id
  ) THEN
    RAISE EXCEPTION 'a card must place a note of the board workspace';
  END IF;
  RETURN NEW;
END;
$$;

-- AFTER, so a missing board/note is reported by the foreign key first and this
-- trigger only adds the cross-workspace rule.
CREATE TRIGGER cards_protect_note_workspace
AFTER INSERT OR UPDATE OF board_id, note_id ON app.cards
FOR EACH ROW EXECUTE FUNCTION app.protect_card_note_workspace();
